def generate_and_test(seed, generate, validate, attempts=100):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    tried = 0
    reasons = {}
    for offset in range(attempts):
        tried += 1
        candidate = generate(seed + offset)
        failures = validate(candidate)
        if not failures:
            return {"content": candidate, "seed": seed + offset,
                    "attempts": tried, "accepted": True, "reasons": reasons}
        for reason in failures:
            reasons[reason] = reasons.get(reason, 0) + 1
    return {"content": None, "seed": None, "attempts": tried,
            "accepted": False, "reasons": reasons}


def expressive_range(seeds, generate, measures):
    if not seeds:
        raise ValueError("no seeds")
    rows = []
    for seed in seeds:
        content = generate(seed)
        rows.append({name: measure(content) for name, measure in measures.items()})
    summary = {}
    for name in measures:
        values = [row[name] for row in rows]
        summary[name] = {"min": min(values), "max": max(values),
                         "distinct": len(set(values))}
    return summary
